const inputData = $input.first().json;
const items = inputData.result || [];

let cpu = "N/D";
let ramLibre = "N/D";
let discoUsado = "N/D";
let cargaSistema = "N/D";
let uptimeStr = "N/D";

let cpuNum = 0;
let ramNum = 0;
let discoNum = 0;

items.forEach(item => {
  const val = parseFloat(item.lastvalue);
  const key = item.key_ || "";

  if (key === "system.cpu.util") {
    cpuNum = !isNaN(val) ? val : 0;
    cpu = !isNaN(val) ? val.toFixed(2) + "%" : item.lastvalue;
  } else if (key === "vm.memory.size[pavailable]") {
    ramNum = !isNaN(val) ? (100 - val) : 0;
    ramLibre = !isNaN(val) ? (100 - val).toFixed(2) + "%" : item.lastvalue;
  } else if (key.includes("vfs.fs.") && key.includes("/,pused")) {
    discoNum = !isNaN(val) ? val : 0;
    discoUsado = !isNaN(val) ? val.toFixed(2) + "%" : item.lastvalue;
  } else if (key.includes("system.cpu.load")) {
    cargaSistema = !isNaN(val) ? val.toFixed(2) : item.lastvalue;
  } else if (key === "system.uptime") {
    if (!isNaN(val)) {
      const dias = Math.floor(val / 86400);
      const horas = Math.floor((val % 86400) / 3600);
      const mins = Math.floor((val % 3600) / 60);
      uptimeStr = `${dias}d ${horas}h ${mins}m`;
    }
  }
});

// Función para determinar el emoji según el porcentaje
function getEmoji(val) {
  if (val >= 80) return "🔴";
  if (val >= 60) return "🟡";
  return "🟢";
}

const emojiCpu = getEmoji(cpuNum);
const emojiRam = getEmoji(ramNum);
const emojiDisco = getEmoji(discoNum);

// Evalúa si supera el umbral crítico
const esCritico = cpuNum > 80 || ramNum > 80;

const mensaje = `💻 *ESTADO DEL MINIPC*

${emojiCpu} *Uso de CPU:* ${cpu}
${emojiRam} *Uso de RAM:* ${ramLibre}
${emojiDisco} *Disco Principal (/):* ${discoUsado} usado
⚡ *Carga del sistema (1m):* ${cargaSistema}
⏱️ *Tiempo encendido:* ${uptimeStr}`;

return [{ json: { esCritico, mensaje } }];

const inputData = $input.first().json;
const items = inputData.result || [];

let cpu = "N/D", ramLibre = "N/D", discoUsado = "N/D", cargaSistema = "N/D", uptimeStr = "N/D";
let cpuNum = 0, ramNum = 0, discoNum = 0;

items.forEach(item => {
  const val = parseFloat(item.lastvalue);
  const key = item.key_ || "";

  if (key === "system.cpu.util") {
    cpuNum = !isNaN(val) ? val : 0;
    cpu = !isNaN(val) ? val.toFixed(2) + "%" : item.lastvalue;
  } else if (key === "vm.memory.size[pavailable]") {
    ramNum = !isNaN(val) ? (100 - val) : 0;
    ramLibre = !isNaN(val) ? (100 - val).toFixed(2) + "%" : item.lastvalue;
  } else if (key.includes("vfs.fs.") && key.includes("/,pused")) {
    discoNum = !isNaN(val) ? val : 0;
    discoUsado = !isNaN(val) ? val.toFixed(2) + "%" : item.lastvalue;
  } else if (key.includes("system.cpu.load")) {
    cargaSistema = !isNaN(val) ? val.toFixed(2) : item.lastvalue;
  } else if (key === "system.uptime") {
    if (!isNaN(val)) {
      const dias = Math.floor(val / 86400);
      const horas = Math.floor((val % 86400) / 3600);
      const mins = Math.floor((val % 3600) / 60);
      uptimeStr = `${dias}d ${horas}h ${mins}m`;
    }
  }
});

function getEmoji(val) {
  if (val >= 80) return "🔴";
  if (val >= 60) return "🟡";
  return "🟢";
}

const emojiCpu = getEmoji(cpuNum);
const emojiRam = getEmoji(ramNum);
const emojiDisco = getEmoji(discoNum);

// Evaluación de límites críticos (CPU > 80%, RAM > 80% o Disco > 85%)
const esCriticoActual = cpuNum > 80 || ramNum > 80 || discoNum > 85;

// Estado previo guardado en n8n estático
const staticData = $getWorkflowStaticData('global');
const estuvoCritico = staticData.estuvoCritico || false;

let enviarNotificacion = false;
let encabezado = "";

if (esCriticoActual) {
  enviarNotificacion = true;
  encabezado = "🚨 *ALERTA CRÍTICA DETECTADA* 🚨";
  staticData.estuvoCritico = true;
} else if (estuvoCritico && !esCriticoActual) {
  enviarNotificacion = true;
  encabezado = "🟢 *SISTEMA NORMALIZADO / RECUPERADO* 🟢";
  staticData.estuvoCritico = false;
}

const mensaje = `${encabezado}

${emojiCpu} *Uso de CPU:* ${cpu}
${emojiRam} *Uso de RAM:* ${ramLibre}
${emojiDisco} *Disco Principal (/):* ${discoUsado} usado
⚡ *Carga del sistema (1m):* ${cargaSistema}
⏱️ *Tiempo encendido:* ${uptimeStr}`;

return [{ json: { esCritico: enviarNotificacion, mensaje } }];

const ahora = Date.now();
const ventanaMs = 60 * 60 * 1000; // última hora

let incidentesActivos = [];

// $input.all() nos da TODOS los items (cada uno es un evento/incidente distinto)
const items = $input.all();

items.forEach(entrada => {
  const evento = entrada.json;

  if (!evento.event_log || evento.event_log.length === 0) return;

  const ultimoLog = evento.event_log[evento.event_log.length - 1];
  const timestampMs = ultimoLog.timestamp > 9999999999 
    ? ultimoLog.timestamp 
    : ultimoLog.timestamp * 1000;

  const esReciente = (ahora - timestampMs) < ventanaMs;
  const pareceResuelto = /restored|resolved|recovered|normal operations/i.test(ultimoLog.message || "");

  if (esReciente && !pareceResuelto) {
    incidentesActivos.push({
      region: evento.region_name,
      resumen: evento.summary,
      ultimoMensaje: ultimoLog.summary
    });
  }
});

return [{ json: { proveedor: "AWS", incidentesActivos, hayIncidente: incidentesActivos.length > 0 } }];

const data = $input.first().json;
const indicator = data.status.indicator;
const descripcion = data.status.description;

// none = todo bien. minor/major/critical = hay problema
const hayIncidente = indicator !== "none";

return [{ 
  json: { 
    proveedor: "Cloudflare", 
    hayIncidente, 
    gravedad: indicator, 
    descripcion 
  } 
}];

const allItems = $input.all();

// Mapeo unificado para corregir nombres dispares (ej. Azure vs Microsoft Azure)
const nombresFijos = [
  "AWS", "Cloudflare", "Google Cloud", "GitHub",
  "OpenAI", "Slack", "Discord", "Atlassian", "Azure", "Google News"
];

const proveedoresReales = ["AWS", "Cloudflare", "Google Cloud", "GitHub", "OpenAI", "Slack", "Discord", "Atlassian", "Azure", "Google News"];

let listaServicios = nombresFijos.map(nombreFijo => {
  // Buscar coincidencia flexible por proveedor o nombre (normalizando texto)
  const item = allItems.find(i => {
    const p = (i.json.proveedor || i.json.nombre || "").toLowerCase();
    const target = nombreFijo.toLowerCase();
    return p.includes(target) || target.includes(p);
  });

  if (!item) {
    return { nombre: nombreFijo, estado: "⚪ No monitorizado" };
  }

  if (!proveedoresReales.includes(nombreFijo)) {
    // Si el nodo de entrada ya trae un estado predefinido, úsalo; si no, pon el placeholder
    const estadoEntrada = item.json.estado;
    if (estadoEntrada) {
      return { nombre: nombreFijo, estado: estadoEntrada };
    }
    return { nombre: nombreFijo, estado: "⚠️ Placeholder (sin conectar aún)" };
  }

  const hayIncidente = item.json.hayIncidente === true;
  return {
    nombre: nombreFijo,
    estado: hayIncidente ? "🔴 Incidente activo" : "🟢 Operativo"
  };
});

const hayAlertas = listaServicios.some(s => s.estado.includes("🔴"));
const incidentesTexto = listaServicios
  .filter(s => s.estado.includes("🔴"))
  .map(s => `🟠 ${s.nombre}`)
  .join("\n");

const mensaje = hayAlertas
  ? `🌐 ALERTA DE SERVICIOS GLOBALES\n\n${incidentesTexto}`
  : "✅ Todos los servicios operativos";

return [{ json: { servicios: listaServicios, hayAlertas, mensaje } }];

const items = $input.all();
const ahora = Date.now();
const ventanaMs = 60 * 60 * 1000; // última hora

let incidentesActivos = [];

items.forEach(entrada => {
  const inc = entrada.json;

  // Si no tiene fecha de "end", el incidente sigue abierto
  if (!inc.end) {
    incidentesActivos.push({ resumen: inc.external_desc, producto: inc.service_name });
    return;
  }

  const finMs = new Date(inc.end).getTime();
  const esReciente = (ahora - finMs) < ventanaMs;

  if (esReciente) {
    incidentesActivos.push({ resumen: inc.external_desc, producto: inc.service_name });
  }
});

return [{ json: { proveedor: "Google Cloud", incidentesActivos, hayIncidente: incidentesActivos.length > 0 } }];

const data = $input.first().json;
const indicator = data.status.indicator;
return [{ json: { proveedor: "GitHub", hayIncidente: indicator !== "none", gravedad: indicator, descripcion: data.status.description } }];

const data = $input.first().json;
const indicator = data.status.indicator;
return [{ json: { proveedor: "OpenAI", hayIncidente: indicator !== "none", gravedad: indicator, descripcion: data.status.description } }];

try {
  const data = $input.first().json;
  // Slack devuelve un array de incidentes activos si los hay
  const incidentes = data.active_incidents || [];
  const hayIncidente = incidentes.length > 0;
  const descripcion = hayIncidente ? (incidentes[0].title || "Incidente activo en Slack") : "Operativo";

  return [{ 
    json: { 
      proveedor: "Slack", 
      hayIncidente: hayIncidente, 
      descripcion: descripcion 
    } 
  }];
} catch (error) {
  return [{ 
    json: { 
      proveedor: "Slack", 
      hayIncidente: false, 
      descripcion: "Operativo" 
    } 
  }];
}

const data = $input.first().json;
const indicator = data.status.indicator;
return [{ json: { proveedor: "Discord", hayIncidente: indicator !== "none", gravedad: indicator, descripcion: data.status.description } }];

const data = $input.first().json;
const indicator = data.status.indicator;
return [{ json: { proveedor: "Atlassian", hayIncidente: indicator !== "none", gravedad: indicator, descripcion: data.status.description } }];

try {
  const json = $input.first().json;

  // Buscamos los items de forma segura sin importar si varían las mayúsculas o la ruta
  const channel = json?.rss?.channel || json?.feed;
  const items = channel?.item || channel?.entry || [];
  const primerItem = Array.isArray(items) ? items[0] : items;

  // Extraemos el título de forma robusta
  let titulo = "Sin datos recientes";
  if (primerItem) {
    if (typeof primerItem.title === 'string') {
      titulo = primerItem.title;
    } else if (Array.isArray(primerItem.title)) {
      titulo = primerItem.title[0];
    } else if (primerItem.title?._) {
      titulo = primerItem.title._;
    }
  }

  // Detectamos si hay incidencias en el texto
  const textoLower = String(titulo).toLowerCase();
  const hayIncidente = textoLower.includes("active") || 
                       textoLower.includes("incident") || 
                       textoLower.includes("degraded") ||
                       textoLower.includes("outage");

  return [{ 
    json: { 
      proveedor: "Azure", 
      hayIncidente: hayIncidente, 
      descripcion: titulo 
    } 
  }];
} catch (error) {
  return [{ 
    json: { 
      proveedor: "Azure", 
      hayIncidente: false, 
      descripcion: "Error al leer feed: " + error.message 
    } 
  }];
}

const items = $input.first().json.rss.channel.item;
const ahora = Date.now();
const ventanaMs = 6 * 60 * 60 * 1000; // últimas 6 horas

// Palabras que indican un incidente REAL de servicio
const palabrasIncidente = /sin (internet|servicio|cobertura|conexión|teléfono|móvil)|caída (masiva|nacional|de red|en toda españa)|no funciona|apagón|sin luz|corte de (cable|fibra)|incidencia (general|nacional)/i;

// Palabras que indican que es ruido (bolsa, deportes, entretenimiento) a excluir aunque contengan "cae"
const palabrasRuido = /acción|bolsa|dividendo|cotiza|inversores|nasdaq|deportivo|baloncesto|vuelta|equipo|serie|película|catálogo|plus\+/i;

let incidentesReales = [];

items.forEach(item => {
  const titulo = item.title || "";
  const fechaMs = new Date(item.pubDate).getTime();
  const esReciente = (ahora - fechaMs) < ventanaMs;

  if (esReciente && palabrasIncidente.test(titulo) && !palabrasRuido.test(titulo)) {
    incidentesReales.push({
      titular: titulo,
      fuente: item.source?._  || "Google News",
      fecha: item.pubDate
    });
  }
});

return [{
  json: {
    proveedor: "Telecom News",
    hayIncidente: incidentesReales.length > 0,
    incidentesActivos: incidentesReales
  }
}];
